def transform(g):
    H=len(g); W=len(g[0])
    line=[i for i,r in enumerate(g) if all(v==5 for v in r)][0]
    cols={}
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v not in (0,5): cols.setdefault(v,[]).append((r,c))
    below=[(r,c) for col,cells in cols.items() for r,c in cells if r>line]
    bcol=next(col for col,cells in cols.items() if any(r>line for r,c in cells))
    b_r0=min(r for r,c in below); b_c0=min(c for r,c in below)
    cells_by_col={}
    for r,c in below:
        cells_by_col.setdefault(col,[])
    for r,c in below: cells_by_col[bcol].append((r,c))
    # symmetric-shape check per above color
    def bbox(cells):
        rs=[r for r,c in cells]; cs=[c for r,c in cells]
        return min(rs),max(rs),min(cs),max(cs)
    def sym(cells):
        r0,r1,c0,c1=bbox(cells)
        s={(r-r0,c-c0) for r,c in cells}
        h=r1-r0+1; w=c1-c0+1
        return s=={(h-1-r,w-1-c) for r,c in s}
    kept=[]
    for col,cells in cols.items():
        if col==bcol: continue
        rs=[r for r,c in cells]
        if min(rs)>line: continue
        if sym(cells):
            r0,r1,c0,c1=bbox(cells)
            kept.append((c1,col,[(r-r0,c-c0) for r,c in cells],r1-r0+1))
    kept.sort(reverse=True)
    out=[[0]*W for _ in range(H-line-1)]
    for r,c in below: out[r-line-1][c]=bcol
    rr=b_r0-line-1
    for _,col,rel,hh in kept:
        rr-=hh
        for r,c in rel: out[rr+r][c+b_c0]=col
    return out
